from taf.fdsw.rc.schemas.base import SchemaField, SchemaObject
from taf.fdsw.rc.schemas.FDSW18A.autoconnection import AutoConnection


class AutoconnectionSiteParameters(SchemaObject):
    site_id = SchemaField(name="siteId")

    def __init__(self, site_id):
        self.site_id = site_id
        super(AutoconnectionSiteParameters, self).__init__()


class AutoConnection18SP(AutoConnection):
    autoconnection_site_parameters = SchemaField(name="autoconnectionSiteParameters", klass=AutoconnectionSiteParameters)

    def __init__(self, autoconnection_site_parameters, **kwargs):
        super(AutoConnection18SP, self).__init__(**kwargs)
        self.autoconnection_site_parameters = autoconnection_site_parameters


class Site_Identification18SP(SchemaObject):
    bts_id = SchemaField(name="btsId")
    serial_number = SchemaField(name="serialNumber")
    module_version = SchemaField(name="moduleVersion")
    coordinates = SchemaField(name="coordinates")

    def __init__(self, bts_id, serial_number, module_version, coordinates):
        super(Site_Identification18SP, self).__init__()
        self.bts_id = bts_id
        self.serial_number = serial_number
        self.module_version = module_version
        self.coordinates = coordinates
